/**
 * TTOken Code issues board: the GitHub issues of the Session's repository in four columns (to do, agent working,
 * in review, done), with a details panel that opens an agent Session for an issue or for its failing pull request.
 * The board keeps a dark surface in both app themes.
 * Generated by ttoken/apply-brand.mjs from ttoken/forge/client/IssuesBoard.tsx; edit it there.
 */

import { useEffect, useMemo, useRef, useState, type KeyboardEvent, type ReactElement } from 'react'
import clsx from 'clsx'
import type { SessionSummary } from '@deepseek-ai/dsh-api-session-controller/client'
import type { ObservableSnapshot } from '@deepseek-ai/dsh-client-store'
import type { ConvViewProps } from '@deepseek-ai/dsh-client-ui-conversation/client'
import { relativeTime, Switch } from '@deepseek-ai/dsh-client-ui-primitives'
import type {} from '@deepseek-ai/dsh-client-ui-session/client'
import type { InjectFace, PropsLocale } from '@deepseek-ai/dsh-client-ui-slots'
import type { ForgeIssue, ForgeIssuePullRequest } from '@deepseek-ai/dsh-experimental-forge/types'
import type { SessionId } from '@deepseek-ai/dsh-session/types'
import type { RemoteResult } from '@deepseek-ai/dsh-typert-protocol'
import { assertNever } from '@deepseek-ai/dsh-util-values'
import type { ForgeIssueBoard } from '../../types.ts'
import { agentsOf, type AgentSessions } from './agents.ts'
import css from './IssuesBoard.module.css'

/** Milliseconds between two automatic reads while the board is shown. */
const REFRESH_MS = 60_000
/** Least time after a read before a regained window focus reads again. */
const FOCUS_REFRESH_MS = 15_000
/** Milliseconds between two updates of the relative times the board shows. */
const CLOCK_MS = 30_000
/** Labels a card shows; the details panel shows every label. */
const CARD_LABELS = 3
/** Longest part of a branch name taken from an issue title. */
const SLUG_LIMIT = 40

type Translate = PropsLocale<'ttoken.issues'>['t']
type Column = 'todo' | 'working' | 'review' | 'done'
type Filter = 'all' | 'agent' | 'mine'
type AgentState = 'draft' | 'running' | 'waiting'

const COLUMNS: readonly Column[] = ['todo', 'working', 'review', 'done']
const FILTERS: readonly Filter[] = ['all', 'agent', 'mine']
const DOT_CLASS: Readonly<Record<Column, string | undefined>> = {
  todo: css.dotTodo, working: css.dotWorking, review: css.dotReview, done: css.dotDone,
}

/** What the board asks for when it starts an agent Session. */
export interface AgentRequest {
  /** Repository key `host/owner/name`. */
  readonly repository: string
  /** Issue the Session works on. */
  readonly issue: number
  /** First message, placed in the new Session's draft for the user to send. */
  readonly prompt: string
  /** Branch of the Session's worktree; null for a generated name. */
  readonly branch: string | null
}

/** Outcome of starting an agent Session. */
export type AgentStart =
  | { readonly kind: 'started'; readonly sessionId: SessionId }
  /** A later navigation replaced the opening before the Session was shown. */
  | { readonly kind: 'superseded' }
  | { readonly kind: 'failed'; readonly message: string }

/** Business face injected by the board's view registration. */
export interface IssuesBoardInjected {
  hooks: {
    /** Remembered agent Sessions; InjectFace exposes it as `useAgents`. */
    agents: ObservableSnapshot<AgentSessions>
  }
  /**
   * Read the issues board of the Session's repository.
   * @param signal - cancellation of the read.
   * @returns the board, or the forge panel failure.
   */
  load: (signal: AbortSignal) => Promise<RemoteResult<ForgeIssueBoard>>
  /**
   * Open a new Session in the Session's Workspace with the request's first message as its draft, prepare its branch,
   * and remember it for the issue.
   * @param request - what the Session works on.
   * @returns whether the Session opened; never rejects.
   */
  start: (request: AgentRequest) => Promise<AgentStart>
  /**
   * Forget the agent Session remembered for an issue.
   * @param repository - repository key `host/owner/name`.
   * @param issue - issue number.
   */
  forget: (repository: string, issue: number) => void
  /**
   * Show a Session.
   * @param sessionId - Session to show.
   */
  openSession: (sessionId: SessionId) => void
  /**
   * Open a URL outside the app.
   * @param url - web URL.
   */
  openLink: (url: string) => void
}

/** Full props of the issues board view. */
export type IssuesBoardProps = ConvViewProps & InjectFace<IssuesBoardInjected> & PropsLocale<'ttoken.issues'>

/** Why the last read failed. */
interface ReadFailure {
  /** Remote error code, such as `forgePanel/issues-unavailable`. */
  readonly code: string
  /** Host message. */
  readonly message: string
}

/** One issue placed on the board. */
interface IssueRow {
  readonly issue: ForgeIssue
  readonly column: Column
  /** Remembered agent Session that still exists. */
  readonly agent: SessionSummary | null
  /** Open pull request in review, or the merged one of a done issue. */
  readonly pull: ForgeIssuePullRequest | null
}

/**
 * The issues board view.
 * @param props - view props with the board's injected face.
 * @returns the board.
 */
export function IssuesBoard(props: IssuesBoardProps): ReactElement {
  const { t, useAgents, useSessions, load, start, forget, openSession, openLink } = props
  const [board, setBoard] = useState<ForgeIssueBoard | null>(null)
  const [syncedAt, setSyncedAt] = useState<number | null>(null)
  const [syncing, setSyncing] = useState(true)
  const [failure, setFailure] = useState<ReadFailure | null>(null)
  const [filter, setFilter] = useState<Filter>('all')
  const [query, setQuery] = useState('')
  const [selected, setSelected] = useState<number | null>(null)
  const [now, setNow] = useState(() => Date.now())
  const [starting, setStarting] = useState<number | null>(null)
  const [startFailure, setStartFailure] = useState<{ readonly issue: number; readonly message: string } | null>(null)
  const read = useRef<() => void>(() => {})
  const allAgents = useAgents(value => value)
  const sessions = useSessions(state => state.byId)

  useEffect(() => {
    let reader: AbortController | null = null
    let last = 0
    const run = (): void => {
      reader?.abort()
      const controller = new AbortController()
      reader = controller
      last = Date.now()
      setSyncing(true)
      void load(controller.signal).then((result) => {
        if (controller.signal.aborted) return
        setSyncing(false)
        setNow(Date.now())
        if (result.ok) {
          setBoard(result.value)
          setSyncedAt(Date.now())
          setFailure(null)
        } else {
          setFailure({ code: result.error.code, message: result.error.message })
        }
      }, (error: unknown) => {
        if (controller.signal.aborted) return
        setSyncing(false)
        setFailure({ code: 'unknown', message: error instanceof Error ? error.message : String(error) })
      })
    }
    read.current = run
    run()
    const timer = window.setInterval(run, REFRESH_MS)
    const clock = window.setInterval(() => { setNow(Date.now()) }, CLOCK_MS)
    const onFocus = (): void => { if (Date.now() - last >= FOCUS_REFRESH_MS) run() }
    window.addEventListener('focus', onFocus)
    return () => {
      window.clearInterval(timer)
      window.clearInterval(clock)
      window.removeEventListener('focus', onFocus)
      reader?.abort()
    }
  }, [load])

  const repository = board === null ? null : `${board.host}/${board.repository}`
  const remembered = useMemo(() => repository === null ? {} : agentsOf(allAgents, repository), [allAgents, repository])
  const rows = useMemo(() => board === null ? [] : rowsOf(board, remembered, sessions), [board, remembered, sessions])
  const visible = useMemo(() => {
    const needle = query.trim().toLowerCase()
    return rows.filter(row => matchesFilter(row, filter, board?.viewer ?? null) && matchesQuery(row.issue, needle))
  }, [rows, filter, query, board])
  // A filter or search that hides the selected issue closes its details.
  const current = visible.find(row => row.issue.number === selected) ?? null

  const begin = (request: AgentRequest): void => {
    setStarting(request.issue)
    setStartFailure(null)
    void start(request).then((outcome) => {
      setStarting(null)
      if (outcome.kind === 'failed') setStartFailure({ issue: request.issue, message: outcome.message })
    }, (error: unknown) => {
      setStarting(null)
      setStartFailure({ issue: request.issue, message: error instanceof Error ? error.message : String(error) })
    })
  }

  const syncLabel = syncing
    ? t('syncing')
    : failure !== null ? t('failed')
      : syncedAt === null ? t('refresh') : t('synced', { time: agoOf(syncedAt, now, t) })

  return (
    <div className={css.root} data-conversation-composer-overlay="">
      <div className={css.surface}>
        <header className={css.toolbar}>
          <h2 className={css.heading}>{t('title')}</h2>
          {board !== null && (
            <span className={css.repo}>
              <RepositoryGlyph />
              <span className={css.repoName}>{board.repository}</span>
            </span>
          )}
          <div role="group" aria-label={t('filter.label')} className={css.filters}>
            {FILTERS.map(id => (
              <button key={id} type="button" aria-pressed={filter === id} className={css.filter} onClick={() => { setFilter(id) }}>
                {t(`filter.${id}`)}
              </button>
            ))}
          </div>
          <span className={css.spacer} />
          <button type="button" className={css.sync} title={t('refresh')} disabled={syncing} onClick={() => { read.current() }}>
            <span aria-hidden="true" className={clsx(css.syncDot, syncing && css.syncDotBusy, !syncing && failure !== null && css.syncDotFailed)} />
            {syncLabel}
          </button>
          <input
            type="search"
            className={css.search}
            placeholder={t('search.label')}
            aria-label={t('search.label')}
            value={query}
            onChange={(event) => { setQuery(event.target.value) }}
          />
          <button
            type="button"
            className={css.newIssue}
            disabled={board === null}
            onClick={() => { if (board !== null) openLink(newIssueUrl(board)) }}
          >
            <PlusGlyph />
            {t('newIssue')}
          </button>
        </header>
        <div className={css.body}>
          {board === null
            ? <BoardState failure={failure} t={t} retry={() => { read.current() }} />
            : (
              <div className={css.columns}>
                {COLUMNS.map((column) => {
                  const cards = visible.filter(row => row.column === column)
                  return (
                    <section key={column} className={css.column} aria-label={t(`column.${column}`)}>
                      <div className={css.columnHead}>
                        <span aria-hidden="true" className={clsx(css.dot, DOT_CLASS[column])} />
                        <h3 className={css.columnTitle}>{t(`column.${column}`)}</h3>
                        <span className={css.count}>{cards.length}</span>
                      </div>
                      <div className={css.cards}>
                        {cards.map(row => (
                          <IssueCard
                            key={row.issue.number}
                            row={row}
                            selected={row.issue.number === selected}
                            onSelect={() => { setSelected(row.issue.number === selected ? null : row.issue.number) }}
                            now={now}
                            t={t}
                          />
                        ))}
                        {cards.length === 0 && <p className={css.empty}>{t('empty')}</p>}
                      </div>
                    </section>
                  )
                })}
              </div>
            )}
          {board !== null && repository !== null && current !== null && (
            <IssueDetails
              key={current.issue.number}
              row={current}
              board={board}
              repository={repository}
              now={now}
              t={t}
              starting={starting === current.issue.number}
              failure={startFailure?.issue === current.issue.number ? startFailure.message : null}
              onClose={() => { setSelected(null) }}
              onStart={begin}
              onForget={() => { forget(repository, current.issue.number) }}
              openSession={openSession}
              openLink={openLink}
            />
          )}
        </div>
      </div>
    </div>
  )
}

/** Props of the board's place-holding states. */
interface BoardStateProps {
  readonly failure: ReadFailure | null
  readonly t: Translate
  readonly retry: () => void
}

/** The board before its first successful read: reading, no repository, not a checkout, or a failed read. */
function BoardState({ failure, t, retry }: BoardStateProps): ReactElement {
  if (failure === null) return <div className={css.state}><p className={css.stateNote}>{t('loading')}</p></div>
  if (failure.code === 'forgePanel/issues-unavailable') {
    return (
      <div className={css.state}>
        <p className={css.stateTitle}>{t('unavailable')}</p>
        <p className={css.stateNote}>{t('unavailable.note')}</p>
      </div>
    )
  }
  if (failure.code === 'forgePanel/not-a-checkout') {
    return <div className={css.state}><p className={css.stateTitle}>{t('notCheckout')}</p></div>
  }
  return (
    <div className={css.state}>
      <p className={css.stateTitle}>{t('failed')}</p>
      <p className={css.stateNote}>{failure.message}</p>
      <button type="button" className={css.secondary} onClick={retry}>{t('retry')}</button>
    </div>
  )
}

/** Props of one issue card. */
interface IssueCardProps {
  readonly row: IssueRow
  readonly selected: boolean
  readonly onSelect: () => void
  readonly now: number
  readonly t: Translate
}

/** One issue in a column. */
function IssueCard({ row, selected, onSelect, now, t }: IssueCardProps): ReactElement {
  const { issue } = row
  return (
    <button type="button" aria-pressed={selected} className={css.card} onClick={onSelect}>
      <span className={css.cardTop}>
        <span className={css.number}>#{issue.number}</span>
        {issue.labels.slice(0, CARD_LABELS).map(label => <Label key={label.name} name={label.name} color={label.color} />)}
      </span>
      <span className={css.cardTitle}>{issue.title}</span>
      <CardStatus row={row} now={now} t={t} />
    </button>
  )
}

/** The status line at the bottom of a card. */
function CardStatus({ row, now, t }: { readonly row: IssueRow; readonly now: number; readonly t: Translate }): ReactElement {
  switch (row.column) {
    case 'todo':
      return <span className={css.cardMeta}>{metaOf(row.issue, now, t)}</span>
    case 'working':
      return (
        <span className={css.cardLine}>
          <AgentGlyph />
          {t(`card.agent.${agentStateOf(row.agent)}`)}
        </span>
      )
    case 'review':
      return row.pull === null
        ? <span className={css.cardMeta}>{metaOf(row.issue, now, t)}</span>
        : (
          <span className={css.cardLine}>
            <ChecksGlyph pull={row.pull} />
            {pullLineOf(row.pull, t)}
          </span>
        )
    case 'done':
      return (
        <span className={clsx(css.cardLine, css.cardLineMuted)}>
          <MergedGlyph />
          {row.pull === null ? t('card.closed') : t('card.merged', { number: row.pull.number })}
        </span>
      )
    default:
      return assertNever(row.column)
  }
}

/** Props of the details panel. */
interface IssueDetailsProps {
  readonly row: IssueRow
  readonly board: ForgeIssueBoard
  readonly repository: string
  readonly now: number
  readonly t: Translate
  readonly starting: boolean
  readonly failure: string | null
  readonly onClose: () => void
  readonly onStart: (request: AgentRequest) => void
  readonly onForget: () => void
  readonly openSession: (sessionId: SessionId) => void
  readonly openLink: (url: string) => void
}

/** The selected issue: its text and labels, which scroll, above what can be done in its column, which stays in view. */
function IssueDetails(props: IssueDetailsProps): ReactElement {
  const { row, now, t, onClose, openLink } = props
  const { issue } = row
  const body = bodyOf(issue.body)
  const closeOnEscape = (event: KeyboardEvent<HTMLElement>): void => {
    if (event.key === 'Escape') onClose()
  }
  return (
    <aside className={css.drawer} aria-label={t('aside.label')} onKeyDown={closeOnEscape}>
      <div className={css.detailHead}>
        <span className={css.number}>#{issue.number}</span>
        <span className={css.status}>{t(`column.${row.column}`)}</span>
        <span className={css.spacer} />
        <button type="button" className={css.ghost} onClick={() => { openLink(issue.url) }}>
          {t('viewOnGitHub')}
          <ExternalGlyph />
        </button>
        <button type="button" className={css.iconButton} aria-label={t('close')} title={t('close')} onClick={onClose}>
          <CloseGlyph />
        </button>
      </div>
      <div className={css.detailScroll}>
        <h3 className={css.detailTitle}>{issue.title}</h3>
        <p className={css.detailMeta}>{metaOf(issue, now, t)}</p>
        {issue.labels.length > 0 && (
          <div className={css.labels}>
            {issue.labels.map(label => <Label key={label.name} name={label.name} color={label.color} />)}
          </div>
        )}
        <p className={clsx(css.detailBody, body === '' && css.detailBodyEmpty)}>{body === '' ? t('noBody') : body}</p>
      </div>
      <div className={css.detailFoot}>
        <DetailsAction {...props} />
      </div>
    </aside>
  )
}

/** The part of the details panel that depends on the issue's column. */
function DetailsAction(props: IssueDetailsProps): ReactElement {
  const { row, t } = props
  switch (row.column) {
    case 'todo':
      return <Handoff {...props} />
    case 'working':
      return <AgentSession {...props} />
    case 'review':
      return <Review {...props} />
    case 'done':
      return (
        <div className={css.section}>
          <p className={css.checkLine}>
            <MergedGlyph />
            {row.pull === null ? t('done.closed') : t('done.merged', { number: row.pull.number })}
          </p>
          {row.pull !== null && <PullLink pull={row.pull} t={t} openLink={props.openLink} primary={false} />}
        </div>
      )
    default:
      return assertNever(row.column)
  }
}

/** Hand an open issue to a new agent Session on its own branch. */
function Handoff({ row, board, repository, t, starting, failure, onStart }: IssueDetailsProps): ReactElement {
  const { issue } = row
  const [openPr, setOpenPr] = useState(true)
  const [comments, setComments] = useState(false)
  const branch = branchOf(issue)
  const startAgent = (): void => {
    onStart({ repository, issue: issue.number, prompt: issuePrompt(t, board, issue, openPr, comments), branch })
  }
  return (
    <div className={css.section}>
      <h4 className={css.sectionTitle}>{t('handoff.title')}</h4>
      <p className={css.branchLine}>
        {t('handoff.branch')}
        <code className={css.branch}>{branch}</code>
      </p>
      <div className={css.switches}>
        <label className={css.switchRow}>
          <span className={css.switchText}>{t('handoff.openPr')}</span>
          <Switch checked={openPr} onChange={setOpenPr} label={t('handoff.openPr')} className={css.toggle} />
        </label>
        <label className={css.switchRow}>
          <span className={css.switchText}>{t('handoff.comments')}</span>
          <Switch checked={comments} onChange={setComments} label={t('handoff.comments')} className={css.toggle} />
        </label>
      </div>
      <button type="button" className={css.primary} disabled={starting} onClick={startAgent}>
        <MarkGlyph />
        {starting ? t('handoff.starting') : t('handoff.start')}
      </button>
      {failure !== null && <p role="alert" className={css.error}>{t('handoff.failed', { message: failure })}</p>}
      <p className={css.note}>{t('handoff.note')}</p>
    </div>
  )
}

/** The agent Session working on an issue. */
function AgentSession({ row, t, onForget, openSession }: IssueDetailsProps): ReactElement {
  const { agent } = row
  return (
    <div className={css.section}>
      <div className={css.sectionHead}>
        <AgentGlyph />
        <h4 className={css.sectionTitle}>{t('working.title')}</h4>
      </div>
      {agent !== null && <p className={css.sessionTitle}>{agent.displayTitle}</p>}
      <p className={css.note}>{t(`working.${agentStateOf(agent)}`)}</p>
      <div className={css.actions}>
        {agent !== null && (
          <button type="button" className={css.primary} onClick={() => { openSession(agent.id) }}>{t('working.open')}</button>
        )}
        <button type="button" className={css.secondary} onClick={onForget}>{t('working.forget')}</button>
      </div>
    </div>
  )
}

/** The open pull request of an issue in review, with a fix Session when its checks fail. */
function Review({ row, board, repository, t, starting, failure, onStart, openLink }: IssueDetailsProps): ReactElement {
  const { issue, pull } = row
  if (pull === null) return <div className={css.section} />
  const failing = !pull.draft && pull.checks === 'failure'
  const fix = (): void => {
    onStart({ repository, issue: issue.number, prompt: fixPrompt(t, board, issue, pull), branch: null })
  }
  return (
    <div className={css.section}>
      <h4 className={css.sectionTitle}>{t('review.title', { number: pull.number })}</h4>
      <p className={css.checkLine}>
        <ChecksGlyph pull={pull} />
        {pull.draft ? t('review.draft') : t(`review.${pull.checks ?? 'none'}`)}
      </p>
      <div className={css.actions}>
        {failing && (
          <button type="button" className={css.primary} disabled={starting} onClick={fix}>
            <MarkGlyph />
            {starting ? t('handoff.starting') : t('review.fix')}
          </button>
        )}
        <PullLink pull={pull} t={t} openLink={openLink} primary={!failing} />
      </div>
      {failure !== null && <p role="alert" className={css.error}>{t('handoff.failed', { message: failure })}</p>}
      {failing && <p className={css.note}>{t('review.fixNote')}</p>}
    </div>
  )
}

/** Button that opens a pull request on the code host. */
function PullLink({ pull, t, openLink, primary }: {
  readonly pull: ForgeIssuePullRequest
  readonly t: Translate
  readonly openLink: (url: string) => void
  readonly primary: boolean
}): ReactElement {
  return (
    <button type="button" className={primary ? css.primary : css.secondary} onClick={() => { openLink(pull.url) }}>
      {t('review.view')}
      <ExternalGlyph />
    </button>
  )
}

/** One label with its color dot. */
function Label({ name, color }: { readonly name: string; readonly color: string }): ReactElement {
  return (
    <span className={css.label}>
      <span aria-hidden="true" className={css.labelDot} style={{ background: colorOf(color) }} />
      {name}
    </span>
  )
}

/**
 * Place every issue in a column.
 * @param board - the read board.
 * @param remembered - Session ids by issue number.
 * @param sessions - the Session list rows.
 * @returns open issues, then closed ones, in the board's order.
 */
function rowsOf(
  board: ForgeIssueBoard, remembered: Readonly<Record<string, string>>, sessions: Readonly<Record<SessionId, SessionSummary>>,
): IssueRow[] {
  return [...board.open, ...board.closed].map((issue): IssueRow => {
    const id = remembered[String(issue.number)]
    // The stored id names a Session only while the Session list still has it.
    const agent = id === undefined ? null : sessions[id as SessionId] ?? null
    if (issue.state === 'closed') {
      return { issue, column: 'done', agent, pull: issue.pullRequests.find(pull => pull.state === 'merged') ?? null }
    }
    const open = issue.pullRequests.filter(pull => pull.state === 'open')
    const pull = open.find(candidate => !candidate.draft) ?? open[0] ?? null
    if (pull !== null) return { issue, column: 'review', agent, pull }
    return { issue, column: agent === null ? 'todo' : 'working', agent, pull: null }
  })
}

/** Whether a row passes the selected filter; Mine covers issues the signed-in account opened or is assigned. */
function matchesFilter(row: IssueRow, filter: Filter, viewer: string | null): boolean {
  switch (filter) {
    case 'all':
      return true
    case 'agent':
      return row.agent !== null
    case 'mine':
      return viewer !== null && (row.issue.author === viewer || row.issue.assignees.includes(viewer))
    default:
      return assertNever(filter)
  }
}

/** Whether an issue's number, title, or a label contains the lowercase search text. */
function matchesQuery(issue: ForgeIssue, needle: string): boolean {
  if (needle === '') return true
  return `#${issue.number}`.includes(needle)
    || issue.title.toLowerCase().includes(needle)
    || issue.labels.some(label => label.name.toLowerCase().includes(needle))
}

/** Whether an agent Session waits for its first message, works, or waits for the user. */
function agentStateOf(agent: SessionSummary | null): AgentState {
  if (agent === null) return 'waiting'
  if (agent.blank) return 'draft'
  return agent.running ? 'running' : 'waiting'
}

/** Card line of an open pull request. */
function pullLineOf(pull: ForgeIssuePullRequest, t: Translate): string {
  if (pull.draft) return t('card.pr.draft', { number: pull.number })
  return t(`card.pr.${pull.checks ?? 'none'}`, { number: pull.number })
}

/** Who opened an issue, when it last changed, and how many comments it has. */
function metaOf(issue: ForgeIssue, now: number, t: Translate): string {
  const params = { author: issue.author ?? t('ghost'), time: agoOf(Date.parse(issue.updatedAt), now, t), count: issue.comments }
  if (issue.comments === 0) return t('meta', params)
  return t(issue.comments === 1 ? 'meta.oneComment' : 'meta.comments', params)
}

/** How long ago an epoch time was; an unparsable time reads as now. */
function agoOf(at: number, now: number, t: Translate): string {
  const { unit, n } = relativeTime(Number.isFinite(at) ? at : now, now)
  return t(`time.${unit}`, { n })
}

/** An issue body as plain text: without HTML comments, which issue templates leave in, heading marks, and runs of blank lines. */
function bodyOf(body: string): string {
  let text = ''
  let index = 0
  for (;;) {
    const open = body.indexOf('<!--', index)
    if (open < 0) {
      text += body.slice(index)
      break
    }
    text += body.slice(index, open)
    const close = body.indexOf('-->', open + 4)
    if (close < 0) break
    index = close + 3
  }
  return text.split('\n').map(line => line.replace(/^#{1,6} +/, '')).join('\n').replaceAll(/\n{3,}/g, '\n\n').trim()
}

/** Branch for an issue: `ttoken/<number>-<words of the title>`, with only ASCII letters, digits and hyphens. */
function branchOf(issue: ForgeIssue): string {
  const words = issue.title.toLowerCase().normalize('NFKD').split(/[^a-z0-9]+/).filter(word => word !== '')
  let slug = ''
  for (const word of words) {
    const next = slug === '' ? word : `${slug}-${word}`
    if (next.length > SLUG_LIMIT) break
    slug = next
  }
  return slug === '' ? `ttoken/${issue.number}` : `ttoken/${issue.number}-${slug}`
}

/** The repository as `gh --repo` names it: `owner/name` on github.com, `host/owner/name` elsewhere. */
function repoArgumentOf(board: ForgeIssueBoard): string {
  return board.host === 'github.com' ? board.repository : `${board.host}/${board.repository}`
}

/** First message of a Session that works on an issue. */
function issuePrompt(t: Translate, board: ForgeIssueBoard, issue: ForgeIssue, openPr: boolean, comments: boolean): string {
  const params = { number: issue.number, repository: repoArgumentOf(board), title: issue.title, url: issue.url }
  const parts = [t('prompt.issue', params)]
  if (openPr) parts.push(t('prompt.openPr', params))
  if (comments) parts.push(t('prompt.comments', params))
  return parts.join('\n\n')
}

/** First message of a Session that fixes the failing checks of an issue's pull request. */
function fixPrompt(t: Translate, board: ForgeIssueBoard, issue: ForgeIssue, pull: ForgeIssuePullRequest): string {
  return t('prompt.fix', { pull: pull.number, number: issue.number, repository: repoArgumentOf(board), title: issue.title, url: pull.url })
}

/** Web page that opens a new issue in the board's repository. */
function newIssueUrl(board: ForgeIssueBoard): string {
  return `https://${board.host}/${board.repository}/issues/new`
}

/** CSS color of a GitHub label color; a value in another form shows gray. */
function colorOf(color: string): string {
  return /^[0-9a-f]{6}$/i.test(color) ? `#${color}` : '#8f8b82'
}

/** Checks state of a pull request as an icon. */
function ChecksGlyph({ pull }: { readonly pull: ForgeIssuePullRequest }): ReactElement {
  if (pull.draft || pull.checks === null) return <PullGlyph />
  switch (pull.checks) {
    case 'success':
      return (
        <svg className={css.success} width="14" height="14" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
          <path d="M5 10.5l3.2 3.2L15 7" />
        </svg>
      )
    case 'failure':
      return (
        <svg className={css.failure} width="14" height="14" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" aria-hidden="true">
          <path d="M6 6l8 8M14 6l-8 8" />
        </svg>
      )
    case 'pending':
      return (
        <svg className={css.pending} width="14" height="14" viewBox="0 0 20 20" aria-hidden="true">
          <circle cx="10" cy="10" r="4" fill="currentColor" />
        </svg>
      )
    default:
      return assertNever(pull.checks)
  }
}

